import{_ as e}from"./chunks/2022-05-25-10-21-15.upAdkre_.js";import{_ as i,o as a,c as r,a2 as t}from"./chunks/framework.CdjpmwdR.js";const f=JSON.parse('{"title":"路由、代理、网关：边界与关系","description":"本文用网络层级和职责边界拆解路由、代理、网关三个高频概念，给出可落地的区分方法，避免在架构讨论中混用术语。","frontmatter":{"category":"node","date":"2022-05-01","title":"路由、代理、网关：边界与关系","description":"本文用网络层级和职责边界拆解路由、代理、网关三个高频概念，给出可落地的区分方法，避免在架构讨论中混用术语。","tags":["node","api-design"],"image":"/blogs/assets/202205-router-proxy-gtw/2022-05-25-10-21-15.png"},"headers":[],"relativePath":"blogs/2022/202205-router-proxy-gtw.md","filePath":"blogs/2022/202205-router-proxy-gtw.md"}'),o={name:"blogs/2022/202205-router-proxy-gtw.md"};function u(s,l,n,c,d,p){return a(),r("div",null,[...l[0]||(l[0]=[t('<p>在阅读<a href="https://mp.weixin.qq.com/s/B0LVmFvI7kFtjFEM0FG_zw" target="_blank" rel="noreferrer">《为什么需要可编程代理》</a>时，我发现“路由、代理、网关”经常被放在同一语境里讨论，但在很多团队里这三个词的定义并不一致。</p><p>本文尝试用“工作层级 + 主要职责”来统一语义，便于在网络、平台和 API 设计讨论中快速对齐。</p><h2 id="路由-在网络之间转发数据包" tabindex="-1">路由：在网络之间转发数据包 <a class="header-anchor" href="#路由-在网络之间转发数据包" aria-label="Permalink to &quot;路由：在网络之间转发数据包&quot;">​</a></h2><ul><li>路由器 <ul><li>硬件路由 <ul><li>路由器工作在网络的 3 层；</li><li>对其通信两端来说都是透明的，内外网的主机不会查觉中间有路由器参与了操作；</li><li>路由器可以工作在低层，通过直接转化网络地址来转发数据包，它比代理服务器的速度要快；</li></ul></li><li>软（件）路由 <ul><li>结合软件的功能，通过拦截数据包来修改和转发到目标地址</li><li>(软路由更接近于代理服务器)</li></ul></li></ul></li></ul><h2 id="代理-代表客户端或服务端处理请求" tabindex="-1">代理：代表客户端或服务端处理请求 <a class="header-anchor" href="#代理-代表客户端或服务端处理请求" aria-label="Permalink to &quot;代理：代表客户端或服务端处理请求&quot;">​</a></h2><ul><li>代理服务器 <ul><li>代理工作在 3 层以上，通常是 4 层和 7 层；</li><li>局域网中只有代理服务器能上网，只能依托代理服务器进行数据请求和接收，然后再转发； <ul><li>perform some useful service such as caching HTTP content, applying application-level filtering and authorization functions and so on</li></ul></li><li>不同的代理服务器提供不同的服务，通常提供WWW、FTP等常见服务；</li><li>代理通常连接的是两个或多个使用相同协议栈的端点(转发为主)；</li></ul></li><li>代理方式 <ul><li>正向代理 代理外部地址 翻墙 <ul><li>NAT 通过解包，替换目标地址/端口</li></ul></li><li>反向代理 为内部多个机器提供统一的对外地址 <ul><li>负载均衡 对一组相同功能的机器进行的反向代理 <ul><li>(负载均衡是目的，反向代理是实现方式)</li></ul></li></ul></li></ul></li></ul><h2 id="网关-异构网络或系统之间的边界入口" tabindex="-1">网关：异构网络或系统之间的边界入口 <a class="header-anchor" href="#网关-异构网络或系统之间的边界入口" aria-label="Permalink to &quot;网关：异构网络或系统之间的边界入口&quot;">​</a></h2><ul><li>网关 <ul><li>网关是一个概念，不具体特指一类产品，只要连接两个不同的网络的设备都可以叫网关；</li><li>网关通常连接的是两个或多个使用不同协议的端点(协议转换)；</li><li>广义的网关：有进有出即为网关</li><li>狭义的网关 <ul><li>IP路由过程中的网关：子网的关口，所有对子网的访问需要先向网关(默认网关)寻址 <ul><li><a href="https://www.zhihu.com/question/21787311" target="_blank" rel="noreferrer">网关和路由器的区别是什么？</a></li></ul></li><li>API网关：对HTTP API进行拦截、监控、修改、转发</li></ul></li></ul></li></ul><h2 id="总结-先看边界-再看能力" tabindex="-1">总结：先看边界，再看能力 <a class="header-anchor" href="#总结-先看边界-再看能力" aria-label="Permalink to &quot;总结：先看边界，再看能力&quot;">​</a></h2><p><img src="'+e+'" alt="Route vs Proxy vs Gateway"></p><blockquote><p>ps: 还顺便研究了一下 excalidraw 添加中文字体:</p><ul><li>Issue：<a href="https://github.com/excalidraw/excalidraw/issues/5245" target="_blank" rel="noreferrer">https://github.com/excalidraw/excalidraw/issues/5245</a></li><li>Spike：<a href="https://github.com/Anddd7/excalidraw/commit/97eca3fd347c9d3f3875996e7c49585307264e4e" target="_blank" rel="noreferrer">https://github.com/Anddd7/excalidraw/commit/97eca3fd347c9d3f3875996e7c49585307264e4e</a></li><li>Demo：<a href="https://excalidraw-anddd7.vercel.app/" target="_blank" rel="noreferrer">https://excalidraw-anddd7.vercel.app/</a></li></ul></blockquote>',11)])])}const _=i(o,[["render",u]]);export{f as __pageData,_ as default};
